<?php use App\Core\Security;$baseUrl=rtrim((require BASE_PATH.'/config/app.php')['url'],'/');$escape=static fn(mixed $v):string=>Security::escape((string)$v);$students=is_array($students??null)?$students:[];$notifications=is_array($notifications??null)?$notifications:[];$message=$message??null;?>
<section class="dashboard-page admin-workspace"><header class="admin-header"><div class="admin-header-main"><button class="dashboard-menu-toggle" type="button" data-dashboard-toggle aria-expanded="false" aria-controls="dashboard-sidebar" aria-label="Open dashboard menu"><span></span><span></span><span></span></button><p class="eyebrow">ADMIN WORKSPACE</p><h1>Announcements</h1><p>Publish academy updates to all verified students or selected recipients.</p></div></header>
<?php if($message):?><div class="admin-alert admin-alert-success" role="status"><?=$escape($message)?></div><?php endif;?>
<section class="admin-card"><div class="admin-card-header"><div class="admin-card-titles"><h2>Compose announcement</h2><p>Messages are stored in the LMS and linked to recipient accounts.</p></div></div>
<form method="post" action="<?=$escape($baseUrl)?>/admin/announcements/publish" class="admin-form"><input type="hidden" name="_csrf" value="<?=$escape(Security::csrfToken())?>">
<label class="admin-label">Title<input class="admin-input" name="title" required minlength="3" maxlength="200"></label><label class="admin-label">Message<textarea class="admin-textarea" name="body" rows="5" required maxlength="10000"></textarea></label>
<label class="admin-label">Recipients<select class="admin-select" name="audience" data-notification-audience><option value="all_students">All active verified students</option><option value="selected_students">Choose students</option></select></label>
<fieldset class="notification-recipient-picker" data-notification-recipient-picker hidden><legend class="admin-label">Select recipients</legend><?php if($students===[]):?><p class="admin-hint">There are no active verified student accounts.</p><?php else:foreach($students as $student):?><label><input type="checkbox" name="student_ids[]" value="<?=(int)$student['id']?>"><span><strong><?=$escape($student['full_name'])?></strong><small><?=$escape($student['email'])?></small></span></label><?php endforeach;endif;?></fieldset>
<div class="form-actions"><button class="button" type="submit">Publish announcement</button></div></form></section>
<section class="admin-card"><div class="admin-card-header"><div class="admin-card-titles"><h2>Published announcements</h2><p>Latest <?=count($notifications)?> announcement(s)</p></div></div>
